/* @lc app=leetcode id=3915 lang=kotlin */ class Solution { fun up(t: LongArray, v: Int, x: Long) = generateSequence(v) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] = maxOf(t[it], x) } fun qm(t: LongArray, v: Int): Long = generateSequence(v) { it - (it and -it) }.takeWhile { it > 0 }.maxOfOrNull { t[it] } ?: 0L fun maxAlternatingSum(nums: IntArray, k: Int): Long = LongArray(100003).let { bu -> LongArray(100003).let { bd -> LongArray(nums.size).let { su -> LongArray(nums.size).let { sd -> nums.indices.fold(0L) { best, i -> (if (i - k >= 0) up(bu, nums[i - k], su[i - k]).also { up(bd, 100002 - nums[i - k], sd[i - k]) } else Unit).let { sd.set(i, nums[i] + qm(bu, nums[i] - 1)).also { su[i] = nums[i] + qm(bd, 100002 - nums[i] - 1) } }.let { maxOf(best, sd[i], su[i]) } } } } } } }